  "benchmark": "alfworld",
  "description": "Add reusable stage tracking and narrow guidance to stop target-carrying search/loop failures while avoiding hard-coded action forcing.",
  "actions": [
    {
      "type": "add_code_hook",
      "hook": "on_init",
      "code": "def hook(ctx, nb):
    nb['stage'] = 'find_target'
    nb['last_hint'] = ''
    nb['transformed'] = False
    nb['placed_count'] = 0
    text = 'Use ALFWorld order: find and take the target, clean/heat/cool it if the task requires that transform, then put it at the requested destination. For two-object tasks, leave placed targets and use the same destination for the next one.'
    return {'skills': [{'text': text}], 'tool_hint': 'Do not examine, search, or place the target in wrong receptacles after carrying it; use admissible transform or destination put actions.'}"
