      "type": "add_code_hook",
      "hook": "on_post_step",
      "code": "def v(ctx, path, default=None):
    if isinstance(ctx, dict) and path in ctx:
        return ctx.get(path, default)
    cur = ctx
    for part in path.split('.'):
        if isinstance(cur, dict) and part in cur:
            cur = cur.get(part)
        else:
            return default
    return cur

def s(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([s(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([s(k) + ' ' + s(v) for k, v in x.items()])
    return str(x).lower()

def need(task_type):
    if 'clean' in task_type:
        return 'clean'
    if 'heat' in task_type:
        return 'heat'
    if 'cool' in task_type:
        return 'cool'
    return ''

def inv_has(inv, target):
    text = s(inv)
    return bool(target and target in text and 'not carrying' not in text and 'nothing' not in text)

def hook(ctx, nb):
    target = s(v(ctx, 'task.target_type', '') or v(ctx, 'task_type', ''))
    dest = s(v(ctx, 'task.destination_type', ''))
    task_type = s(ctx.get('task.task_type', v(ctx, 'task.task_type', '')))
    inv = v(ctx, 'world.inventory', '')
    act = s(v(ctx, 'action.final_action', '') or v(ctx, 'action.normalized', '') or v(ctx, 'action.raw', ''))
    obs = s(ctx.get('observation', ''))
    if not target:
        return None
    req = need(task_type)
    if req and (act.startswith(req + ' ') or (req + 'ed') in obs or (req + 's') in obs or (req + ' the ') in obs or (req + ' it') in obs)):
        nb['transformed'] = True
    if req and not nb.get('transformed') and not (act.startswith('take ') or act.startswith('put ')) and req + ' ' in obs:
        nb['transformed'] = True
    if act.startswith('put ' + target + ' ') and 'you put' in obs and (' in/on ' + dest or not dest) and (not req or nb.get('transformed')):
        nb['placed_count'] = int(nb.get('placed_count', 0)) + 1
    pc = v(ctx, 'world.placed_count', 0)
    try:
        if int(pc) > int(nb.get('placed_count', 0)):
            nb['placed_count'] = int(pc)
    except Exception:
        pass
    if act.startswith('put ') and 'you put' in obs and ' from ' in act and (' in/on ' + dest or not dest) and (not req or nb.get('transformed')):
        locs = s(v(ctx, 'world.placed_locations', []))
        rest = act[4:]
        item = rest
        if ' from ' in rest:
            item = rest.split(' from ')[0]
        if item and item in locs and locs and dest in locs:
            nb['placed_count'] = int(nb.get('placed_count', 0)) + 1
    holding = inv_has(inv, target)
    inv_text = s(inv)
    wrong = bool(inv_text and 'nothing' not in inv_text and 'not carrying' not in inv_text and not holding)
    admiss = [s(a) for a in (ctx.get('admissible') or [])]
    has_take = any(a.startswith('take ' + target + ' ') for a in admiss)
    has_put = any(a.startswith('put ' + target + ' ') and (not dest or dest in a) for a in admiss)
    has_trans = bool(req and any(a.startswith(req + ' ') for a in admiss))
    nb['wrong_inventory'] = wrong
    if wrong:
        nb['stage'] = 'wrong_inventory'
    elif holding:
        if req and not nb.get('transformed'):
            nb['stage'] = 'transform'
        elif has_put:
            nb['stage'] = 'put_target'
        else:
            nb['stage'] = 'go_destination'
    elif has_take or v(ctx, 'world.target_found', False) or v(ctx, 'world.target_location', ''):
        nb['stage'] = 'take_target' if has_take else 'find_target'
    else:
        nb['stage'] = 'find_target'
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = task_type
    return None"
