def emit(nb, msg):
    if not msg or nb.get('last_hint') == msg:
        return None
    nb['last_hint'] = msg
    return {'message': msg}

def hook(ctx, nb):
    target = nb.get('target_type') or s(v(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or s(v(ctx, 'task.destination_type', ''))
    task_type = nb.get('task_type') or s(v(ctx, 'task.task_type', ''))
    stage = nb.get('stage', 'find_target')
    req = need(task_type)
    req_name = req or 'required clean, heat, or cool transform'
    if not target:
        return None
    admiss = [s(a) for a in (ctx.get('admissible') or [])]
    has_put = any(a.startswith('put ' + target + ' ') and (not dest or dest in a) for a in admiss)
    trans_ok = bool(req and any(a.startswith(req + ' ') for a in admiss))
    if stage == 'wrong_inventory':
        return emit(nb, 'You appear to be carrying a non-target item. Do not place it as the goal object; recover and focus on finding/taking the ' + target + '.')
    if stage == 'transform' and req:
        if trans_ok:
            return emit(nb, 'Use the available ' + req + ' action on the ' + target + ' now; do not put it at the destination before transforming it.')
        return emit(nb, 'Carry the ' + target + ' to a place that can ' + req + ' it, then return to the ' + dest + ' for the final put.')
    if stage == 'put_target' and has_put:
        return emit(nb, 'The ' + target + ' is ready; use the available put action at the ' + dest + ' instead of searching or examining more.')
    if stage == 'go_destination' and (not req or nb.get('transformed')) and dest and (not has_put or (has_put and (ctx.get('predicates.same_action_repeated') or ctx.get('predicates.same_observation_repeated') or ctx.get('predicates.remaining_steps_low')))):
        return emit(nb, 'Stop searching and take the ' + target + ' to the ' + dest + ' for the final put; avoid other receptacles.')
    if stage == 'take_target' and target:
        return emit(nb, 'Find and take a ' + target + ' for the goal; do not confuse it with other objects.')
    return None"
