        return {'kind': 'block_and_prompt', 'message': 'That action is not available in the current state. Choose only from AVAILABLE ACTIONS, or reposition/search until the needed target take, transform, or destination put appears.'}
    holding = bool(nb.get('stage') in ['transform', 'put_target', 'go_destination', 'wrong_inventory']) or bool(v(ctx, 'world.inventory', ''))
    if act.startswith('take ' + target + ' ') and dest and dest in act and nb.get('placed_count', 0) > 0 and (not req or nb.get('transformed')):
        return {'kind': 'block_and_prompt', 'message': 'Do not take back a target already placed at the destination. For two-object tasks, continue with the next target at the same destination.'}
    if holding and req and not nb.get('transformed') and act.startswith('put ' + target + ' ') and (not dest or dest in act) and admiss and any(a.startswith(req + ' ') for a in admiss):
        return {'kind': 'block_and_prompt', 'message': 'Do not place the target at the final destination before the required transform. Use the available clean, heat, or cool action first.'}
    if holding and req and not nb.get('transformed') and dest and act.startswith('put ' + target + ' ') and dest in act and not any(a.startswith(req + ' ') for a in admiss):
        return {'kind': 'block_and_prompt', 'message': 'This premature destination put is likely to fail. Carry the target to a place that can perform the required transform, then return to the destination.'}
    return None"
